-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.review_people(p_site_id uuid)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner,cms_authenticated_user=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.review_people(p_site_id uuid)
 RETURNS TABLE(id uuid, display_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NOT app.has_site_access(p_site_id) AND app.has_scoped_site_access(p_site_id) THEN
    RETURN QUERY SELECT DISTINCT u.id,COALESCE(NULLIF(u.display_name,''),u.email) FROM public.app_users u WHERE u.status='active' AND EXISTS(SELECT 1 FROM public.pages p WHERE p.site_id=p_site_id AND app.has_page_access(p.id) AND app.page_role_as(u.id,p.id) IS NOT NULL) ORDER BY 2;
    RETURN;
  END IF;
  IF NOT app.has_site_access(p_site_id) THEN
    RAISE EXCEPTION 'no such site' USING ERRCODE = 'CMS03';
  END IF;

  RETURN QUERY
  SELECT DISTINCT u.id, COALESCE(NULLIF(u.display_name, ''), u.email)
    FROM public.app_users u
   WHERE u.status = 'active'
     AND (
       EXISTS (SELECT 1 FROM public.site_memberships m
                WHERE m.site_id = p_site_id AND m.user_id = u.id)
       OR EXISTS (SELECT 1 FROM public.global_roles g
                  WHERE g.user_id = u.id AND g.role = 'super_admin')
     )
   ORDER BY 2;
END
$function$
